const makeBtn = async (logoId, scale, name) => {
  const src = await figma.getNodeByIdAsync(logoId);
  const c = figma.createComponent();
  c.name = name;
  c.resize(52, 52);
  c.cornerRadius = 26;
  c.fills = [S('#14141A')];
  c.strokes = [S('#26262E')];
  c.strokeWeight = 1;
  const inst = src.createInstance();
  inst.rescale(scale);
  c.appendChild(inst);
  inst.x = (52 - inst.width) / 2;
  inst.y = (52 - inst.height) / 2;
  const rk = n => { if ('fills' in n && Array.isArray(n.fills) && n.fills.some(f => f.type === 'SOLID')) n.fills = [S('#E8E8EE')]; if ('children' in n) n.children.forEach(rk); };
  rk(inst);
  return c;
};
