  let fills = '';
  if ('fills' in n && Array.isArray(n.fills)) fills = ' f:' + n.fills.map(f => f.type === 'SOLID' ? 'S(' + Math.round(f.color.r*255) + ',' + Math.round(f.color.g*255) + ',' + Math.round(f.color.b*255) + ',' + (f.opacity !== undefined ? f.opacity : 1) + ')' : f.type).join('|');
  let s = ' '.repeat(d) + n.type.charAt(0) + ' [' + n.name + '] ' + Math.round(n.width) + 'x' + Math.round(n.height) + fills;
  if (n.type === 'INSTANCE') { lines.push(s + ' (of ' + n.mainComponent.id + ')'); return; }
  lines.push(s);
  if ('children' in n) n.children.forEach(c => dump(c, d + 1, lines));
};
